# 한 자리씩 곱하고 더하는 과정을 '단계'로 보면, 단계마다 정확도 p 일 때 전체 성공은 p**단계수
def steps_for(a_digits, b_digits):        # 부분곱 a*b 개 + 자리 올림 덧셈 (대략)
    return a_digits * b_digits + (a_digits + b_digits)

for p in (0.99, 0.97):
    row = []
    for n in (1, 2, 3, 4, 5):
        s = steps_for(n, n)
        row.append(f"{n}x{n}:{p ** s:.2f}")
    print(f"p={p}", " ".join(row))

