# Toolformer 식 인라인 호출을 찾아 실행하고 결과를 끼워 넣는다 (계산기·달력 두 도구)
import re, datetime

TOOLS = {
    "Calculator": lambda expr: round(eval(expr, {"__builtins__": {}}), 2),  # 데모용: 숫자식만 넣는다
    "Calendar":   lambda _: datetime.date(2017, 3, 9).strftime("Today is %A, %B %d, %Y"),
}
CALL = re.compile(r"\[(\w+)\(([^)]*)\)\]")      # [이름(인자)] 꼴

def run_inline(text):
    def repl(m):
        name, arg = m.group(1), m.group(2)
        if name not in TOOLS:
            return f"[{name}({arg}) -> ERROR: unknown tool]"
        return f"[{name}({arg}) -> {TOOLS[name](arg)}]"
    return CALL.sub(repl, text)

print(run_inline("Out of 1400 participants, 400 (or [Calculator(400/1400)]) passed."))
print(run_inline("The WL opens on Friday, [Calendar()] March 10."))
print(run_inline("Area is [Calculater(17423*892)]"))   # 오타 난 도구 이름

# ToolkenGPT: 단어 행렬 W_v 아래에 도구 행렬 W_tau 를 이어 붙여 한 softmax 로 다음 토큰을 고른다
import math

W_v = {"the": [0.2, 0.1], "area": [0.1, 0.3], "is": [0.4, 0.0]}     # 단어 임베딩(얼린다)
W_tau = {"<square>": [1.0, 0.8], "<gcd>": [-0.5, 0.2]}              # 툴큰 임베딩(이것만 학습)
h = [1.5, 1.0]                                                      # 직전 은닉 상태 h_{i-1}

def softmax_next(h):
    rows = {**W_v, **W_tau}                                         # [W_v; W_tau]
    logits = {t: sum(a * b for a, b in zip(w, h)) for t, w in rows.items()}
    z = sum(math.exp(v) for v in logits.values())
    return {t: math.exp(v) / z for t, v in logits.items()}

p = softmax_next(h)
for t, v in sorted(p.items(), key=lambda kv: -kv[1]):
    print(f"{t:9s} logit={sum(a*b for a,b in zip({**W_v, **W_tau}[t], h)):5.2f}  p={v:.3f}")
nxt = max(p, key=p.get)
print("다음 토큰:", nxt, "-> 도구 모드로 전환" if nxt in W_tau else "-> 보통 생성 계속")

# Gorilla 식 AST 부분트리 대조: 생성된 호출을 파싱해 API DB 의 어느 항목과 맞는지 본다
import ast

API_DB = [  # (함수 경로, 반드시 맞아야 할 위치 인자)
    ("torch.hub.load", ("pytorch/vision", "densenet121")),
    ("torch.hub.load", ("snakers4/silero-models", "silero_stt")),
]
def parse(call_src):
    node = ast.parse(call_src, mode="eval").body
    if not isinstance(node, ast.Call): return None, ()
    fn = ast.unparse(node.func)
    args = tuple(a.value for a in node.args if isinstance(a, ast.Constant))
    return fn, args

def judge(call_src):
    fn, args = parse(call_src)
    names = {f for f, _ in API_DB}
    if fn not in names: return "hallucination (없는 API)"
    for f, need in API_DB:
        if f == fn and all(x.split(":")[0] == y for x, y in zip(args, need)) and len(args) >= len(need):
            return "correct"
    return "error (있는 API, 틀린 인자)"

for src in ["torch.hub.load('pytorch/vision:v0.10.0', 'densenet121', pretrained=True)",
            "torch.hub.load('pytorch/vision', 'densenet999')",
            "torchaudio.pipelines.WAV2VEC2_ASR('audio.wav')"]:
    print(f"{judge(src):28s} <- {src}")

# function calling 하네스: 스키마 검증 -> 실패하면 오류를 모델에 돌려주고 재시도 (LLM 은 가짜 stub)
import json
SCHEMA = {"name": "get_weather", "parameters": {"type": "object",
          "properties": {"city": {"type": "string"}, "units": {"enum": ["metric", "imperial"]}},
          "required": ["city"]}}
def validate(args, p=SCHEMA["parameters"]):
    errs = [f"missing '{r}'" for r in p["required"] if r not in args]
    for k, v in args.items():
        spec = p["properties"].get(k)
        if spec is None: errs.append(f"unknown arg '{k}'")
        elif "enum" in spec and v not in spec["enum"]: errs.append(f"'{k}' must be one of {spec['enum']}")
        elif spec.get("type") == "string" and not isinstance(v, str): errs.append(f"'{k}' must be string")
    return errs
REPLIES = iter(['{"name":"get_weather","arguments":{"town":"Stanford"}}',          # 1차: 인자 이름 환각
                '{"name":"get_weather","arguments":{"city":"Stanford","units":"kelvin"}}',  # 2차: enum 위반
                '{"name":"get_weather","arguments":{"city":"Stanford","units":"imperial"}}'])
def stub_llm(messages): return next(REPLIES)            # 진짜 LLM 자리 — 정해 둔 답을 차례로 낸다
def get_weather(city, units="metric"): return {"city": city, "temp": 68 if units == "imperial" else 20}
messages = [{"role": "user", "content": "Stanford 날씨?"}]
for attempt in range(1, 4):
    try: call = json.loads(stub_llm(messages))
    except json.JSONDecodeError as e: errs = [f"bad JSON: {e}"]
    else: errs = validate(call["arguments"])
    if not errs:
        print(f"try {attempt}: OK ->", get_weather(**call["arguments"])); break
    print(f"try {attempt}: rejected {errs}")
    messages.append({"role": "tool", "content": "ERROR: " + "; ".join(errs)})   # 오류를 다음 입력에
else:
    print("3번 실패 -> 사용자에게 되묻거나 포기")

# MCP 서버 흉내: JSON-RPC 2.0 으로 tools/list 와 tools/call 에 답한다 (실제 SDK 아님, 메시지 모양만)
import json
TOOLS = [{"name": "weather_current", "description": "Current weather for a location",
          "inputSchema": {"type": "object", "properties": {"location": {"type": "string"}},
                          "required": ["location"]}}]
IMPL = {"weather_current": lambda a: f"Current weather in {a['location']}: 68°F, partly cloudy"}

def handle(raw):
    req = json.loads(raw)
    rid, method, params = req.get("id"), req.get("method"), req.get("params", {})
    if method == "tools/list":
        return {"jsonrpc": "2.0", "id": rid, "result": {"tools": TOOLS}}
    if method == "tools/call":
        name, args = params.get("name"), params.get("arguments", {})
        if name not in IMPL:
            return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32602, "message": f"Unknown tool {name}"}}
        try:
            text, err = IMPL[name](args), False
        except KeyError as e:                      # 도구 실행 오류는 결과 안의 isError 로 돌려준다
            text, err = f"missing argument {e}", True
        return {"jsonrpc": "2.0", "id": rid,
                "result": {"content": [{"type": "text", "text": text}], "isError": err}}
    return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32601, "message": "Method not found"}}

for msg in [{"jsonrpc": "2.0", "id": 2, "method": "tools/list"},
            {"jsonrpc": "2.0", "id": 3, "method": "tools/call", "params": {"name": "weather_current", "arguments": {"location": "Stanford"}}},
            {"jsonrpc": "2.0", "id": 4, "method": "tools/call", "params": {"name": "weather_current", "arguments": {}}}]:
    print(json.dumps(handle(json.dumps(msg)), ensure_ascii=False)[:110])

# 들어오는 쪽(에이전트 토큰)과 나가는 쪽(LMS 토큰)을 가르는 게이트 — 토큰은 서로 넘어가지 않는다
AGENT_SCOPES = {"tok-student-01": {"list_assignments", "get_submissions"},
                "tok-ta-agent":   {"list_assignments", "get_submissions", "post_grade"}}
LMS_TOKEN = "lms-secret"                         # 서버만 안다. 에이전트에게 보이지 않는다

def lms_rest(method, path, body=None):          # 바깥 REST API 자리(가짜)
    return {"status": 200, "via": f"{method} {path}", "auth": "Bearer ***"}   # 토큰은 로그에도 가린다

ROUTES = {"list_assignments": ("GET", "/assignments"), "get_submissions": ("GET", "/submissions"),
          "post_grade": ("POST", "/grade")}

def call_tool(agent_token, tool, args):
    allowed = AGENT_SCOPES.get(agent_token)
    if allowed is None:  return {"isError": True, "text": "401 unknown agent"}
    if tool not in allowed: return {"isError": True, "text": f"403 '{tool}' not permitted"}
    method, path = ROUTES[tool]
    return {"isError": False, "text": lms_rest(method, path, args)}   # 나가는 호출은 서버의 LMS_TOKEN 으로

print(call_tool("tok-student-01", "list_assignments", {}))
print(call_tool("tok-student-01", "post_grade", {"student": "s1", "grade": "A"}))
print(call_tool("tok-ta-agent", "post_grade", {"student": "s1", "grade": "A"}))
